/* ---------- GEOGRAFI 5: Europa & världen ---------- */
function eurMap({w=80,hi={},marks=[],caps=[],route=null,vb=null}={}){const V=vb||[0,0,100,EUR.H];let s=`<svg class="ic" viewBox="${V.join(' ')}" style="width:${w}cqw;height:${(w*V[3]/V[2]).toFixed(1)}cqw;border-radius:2cqw;overflow:hidden" aria-hidden="true"><rect width="100" height="${EUR.H}" rx="3" fill="#D7E8F1"/>`;
 Object.entries(EUR.c).forEach(([k,d])=>{s+=`<path d="${d}" fill="${hi[k]||'#EEE8D8'}" stroke="#fff" stroke-width=".25" stroke-linejoin="round"/>`});
 caps.forEach(c=>{const [n,pos]=Array.isArray(c)?c:[c,'r'];const [x,y]=EUR.cap[n];const tx=pos==='l'?x-1.4:(pos==='b'||pos==='t')?x:x+1.4,ty=pos==='b'?y+4.2:pos==='t'?y-1.8:y+1,an=pos==='l'?'end':(pos==='b'||pos==='t')?'middle':'start';s+=`<circle cx="${x}" cy="${y}" r=".9" fill="var(--ink)"/><text x="${tx}" y="${ty}" text-anchor="${an}" font-size="3.4" font-family="Andika,sans-serif" fill="var(--ink)" stroke="#fff" stroke-width=".6" paint-order="stroke">${n}</text>`});
 if(route)s+=`<path d="M${route.map(n=>EUR.cap[n].join(' ')).join(' L')}" fill="none" stroke="var(--a-lingon)" stroke-width=".7" stroke-dasharray="1.6 1.2"/>`;
 marks.forEach(([t,x,y,lx,ly])=>{if(lx!==undefined){s+=`<path d="M${lx} ${ly} L${x} ${y}" stroke="var(--ink)" stroke-width=".3"/><circle cx="${x}" cy="${y}" r=".6" fill="var(--ink)"/>`;x=lx;y=ly}s+=`<circle cx="${x}" cy="${y}" r="2.6" fill="#fff" stroke="var(--ink)" stroke-width=".35"/><text x="${x}" y="${y+1.1}" font-size="3" font-weight="700" text-anchor="middle" font-family="Andika,sans-serif" fill="var(--ink)">${t}</text>`});
 return s+'</svg>'}
