function rose8(size){let s=rose(size).replace('</svg>','');[['NÖ',45],['SÖ',135],['SV',225],['NV',315]].forEach(([t,a])=>{const r=a*Math.PI/180;s+=`<text x="${(50+44*Math.sin(r)).toFixed(1)}" y="${(50-44*Math.cos(r)+2).toFixed(1)}" font-size="7" text-anchor="middle" font-family="Andika,sans-serif" font-weight="700" fill="var(--ink-soft)">${t}</text>`});[['N',0],['Ö',90],['S',180],['V',270]].forEach(([t,a])=>{const r=a*Math.PI/180;s+=`<text x="${(50+46*Math.sin(r)).toFixed(1)}" y="${(50-46*Math.cos(r)+3).toFixed(1)}" font-size="9" text-anchor="middle" font-family="Fraunces,serif" font-weight="600" fill="var(--ink)">${t}</text>`});return s.replace('viewBox="0 0 100 100"','viewBox="-6 -6 112 112"')+'</svg>'}
